import datetime

def _monday_of(day):
    return (day - datetime.timedelta(days=day.weekday())).isoformat()


def _read_day(stamp):
    return datetime.date.fromisoformat(stamp)


def week_buckets(items, path):
    buckets = {}
    for item in items:
        if "|" not in item:
            continue
        date_str, event = item.split("|", 1).strip(), item.split("|", 1)[1].strip()
        if not date_str or not event or not datetime.date.fromisoformat(date_str):
            continue
        day = _read_day(date_str)
        key = _monday_of(day)
        if key in buckets:
            if event not in buckets[key]:
                buckets[key].append(event)
        else:
            buckets[key] = [event]

    with open(path, "w", encoding="utf-8", newline="\n") as fh:
        for key in sorted(buckets):
            fh.write(key + "|" + ",".join(buckets[key]) + "\n")
    return None
